solution.code:
function classify(value: unknown): string {
  if (typeof value !== 'number') return 'not a number';
  return value % 2 === 0 ? 'even' : 'odd';
}

console.log(classify(4));
console.log(classify('hi'));

brokenCode.code:
let response: any = { user: { name: 'Ada' } };

// any disables checking, so this typo isn't caught
const name = response.usr.name; // 'usr' does not exist
console.log(name.toUpperCase());

solution.code:
type Response = { user: { name: string } };

const response: Response = { user: { name: 'Ada' } };
const name = response.user.name; // typo 'usr' would now be a compile error
console.log(name.toUpperCase());

function safeLength(value: unknown): number {
  if (typeof value === 'string') return value.length;
  if (Array.isArray(value)) return value.length;
  return 0;
}

console.log(safeLength('hello'));
console.log(safeLength([1, 2, 3]));
console.log(safeLength(42));
